SourceCode.Declaration:
/// <summary>
/// Attaches rendered label preview images to the related Work record through the standard
/// document management APIs. Creates the <c>LBLPREV</c> document type when it is missing and
/// finds existing attachments by ZPL hash.
/// </summary>
internal final class AAXWHSLabelAttachmentService
{
    #DEFINE.LabelPreviewDocuTypeId('LBLPREV')
    #DEFINE.ZplHashNotePrefix('ZplHash:')
}

Method.Source:
/// <summary>
/// Creates the <c>LBLPREV</c> document type in the current company if it does not already exist.
/// The document type is per company, so the method can be called from each company-scoped batch chunk.
/// </summary>
public static void ensureDocuType()
{
    // Create the document type when it does not exist in the current company
    if (!DocuType::find(#LabelPreviewDocuTypeId))
    {
        DocuType docuType;

        ttsbegin;
        docuType.TypeId        = #LabelPreviewDocuTypeId;
        docuType.Name          = "@AAXWarehouseTools:DocuTypeLabelPreview";
        docuType.TypeGroup     = DocuTypeGroup::File;
        docuType.FilePlace     = DocuFilePlace::Archive;
        // DocuActionFile is abstract, so use its concrete subclass DocuActionArchive
        docuType.ActionClassId = classNum(DocuActionArchive);
        docuType.insert();
        ttscommit;
    }
}

/// <summary>
/// Attaches a single rendered PNG to the supplied Work record as an <c>LBLPREV</c> attachment.
/// Returns an empty buffer when no Work record is supplied; the caller decides the resulting row state.
/// </summary>
/// <param name = "_work">The Work record the attachment references.</param>
/// <param name = "_png">The PNG image of one rendered label block.</param>
/// <param name = "_fileName">The attachment file name.</param>
/// <param name = "_zplHash">The SHA-256 hash of the final ZPL, stored in the attachment notes.</param>
/// <returns>The created <c>DocuRef</c>, or an empty buffer when no Work record was supplied.</returns>
public static DocuRef attachPng(
    WHSWorkTable    _work,
    container       _png,
    str             _fileName,
    AAXWHSZplHash   _zplHash)
{
    DocuRef docuRef;

    // A missing Work record has no attachment target
    if (!_work.RecId)
    {
        return docuRef;
    }

    System.IO.Stream stream = AAXZplRenderService::pngContainerToStream(_png);

    // The hash in the notes supports the duplicate lookup
    docuRef = DocumentManagement::attachFileForRecord(
        _work,
        #LabelPreviewDocuTypeId,
        stream,
        _fileName,
        _fileName,
        strFmt('%1%2', #ZplHashNotePrefix, _zplHash));

    return docuRef;
}

/// <summary>
/// Indicates whether the Work record already carries an <c>LBLPREV</c> attachment for the given ZPL hash.
/// </summary>
/// <param name = "_work">The Work record to inspect.</param>
/// <param name = "_zplHash">The ZPL hash to look for.</param>
/// <returns>True if a matching attachment already exists; otherwise false.</returns>
public static boolean hasAttachmentWithHash(WHSWorkTable _work, AAXWHSZplHash _zplHash)
{
    if (!_work.RecId || !_zplHash)
    {
        return false;
    }

    DocuRef docuRef;
    str     marker = strFmt('%1%2', #ZplHashNotePrefix, _zplHash);

    // A like predicate is not allowed on the memo Notes field, so the hash is matched in code
    while select Notes from docuRef
        where docuRef.RefTableId   == tableNum(WHSWorkTable)
           && docuRef.RefRecId     == _work.RecId
           && docuRef.RefCompanyId == _work.DataAreaId
           && docuRef.TypeId       == #LabelPreviewDocuTypeId
    {
        if (strScan(docuRef.Notes, marker, 1, strLen(docuRef.Notes)) > 0)
        {
            return true;
        }
    }

    return false;
}
